//! Unit fixtures for the OR-witness semantics (plan26 D4). No solver, no DB,
//! no search: every fixture *declares* rows over a real startpos in
//! `Vec<DbRow>` form, and the startpos's 20 replies are generated by movegen
//! (the "declare every legal reply" helper) rather than typed.

use std::collections::HashMap;

use atomic_solver::notation::{move_to_uci, uci_to_move};
use atomic_solver::position::{Outcome, Position};

use super::super::db::DbRow;
use super::super::merge::DepthStatus;
use super::{Analysis, BoundMode, Claim, Coverage, Flip};

/// One declared row; `path` empty = the startpos root, `ply` = path length.
fn row(
    path: &str,
    outcome: Option<Outcome>,
    bound: Option<u32>,
    status: Option<DepthStatus>,
) -> DbRow {
    DbRow {
        path: if path.is_empty() {
            Vec::new()
        } else {
            path.split(' ').map(str::to_string).collect()
        },
        ply: if path.is_empty() {
            0
        } else {
            path.split(' ').count()
        },
        outcome,
        depth_bound: bound,
        depth_status: status,
    }
}

/// Replay a declared path from the startpos.
fn position(path: &str) -> Position {
    let mut pos = Position::from_fen(Position::STARTPOS_FEN).unwrap();
    for uci in path.split(' ').filter(|s| !s.is_empty()) {
        let mv = uci_to_move(uci, &pos).unwrap();
        pos.do_move(mv);
    }
    pos
}

/// The legal replies of `path`, in movegen order (the analysis's order).
fn legal(path: &str) -> Vec<String> {
    position(path)
        .legal_moves_vec()
        .iter()
        .map(|&m| move_to_uci(m))
        .collect()
}

/// Solve a declared row set to convergence.
fn analyse(rows: &[DbRow]) -> Analysis<'_> {
    let mut an = Analysis::new(rows, Position::STARTPOS_FEN).expect("analysis");
    an.solve().expect("fixpoint converges");
    an
}

/// The cited production shape, minus the spine: two resolved loss replies are
/// enough for the win — the other 18 replies stay unresolved (censored
/// siblings never materialise as rows) and only qualify the bound.
#[test]
fn or_witness_flip_needs_one_loss_reply_not_coverage() {
    let rows = [
        row("", None, None, None),
        row(
            "g1f3",
            Some(Outcome::Loss),
            Some(5),
            Some(DepthStatus::Bound),
        ),
        row(
            "e2e4",
            Some(Outcome::Loss),
            Some(9),
            Some(DepthStatus::Bound),
        ),
    ];
    let an = analyse(&rows);
    let claim = an.claim("").expect("an OR-witness claim");
    assert_eq!(
        claim.value,
        Flip {
            stm_win: true,
            bound: 6
        }
    );
    assert_eq!(claim.coverage, Coverage::OrWitness);
    assert_eq!(claim.bound_mode, BoundMode::Upper);
    assert_eq!(claim.loss_witnesses, 2);
    assert_eq!(claim.unresolved_replies, 18);
    // One pass derives the claim, one confirms the map is unchanged.
    assert_eq!(an.rounds(), 2);
    assert_eq!(an.verify_all().expect("verifies"), 1);
}

/// The derive-once divergence: the round-1 claim (11) is not the converged
/// one (4) because the tightest loss witness is itself only *implied*.
#[test]
fn or_bound_is_the_tightest_resolved_loss() {
    let open_child = "a2a3";
    let root_moves = legal("");
    assert_eq!(root_moves.len(), 20);
    let mut rows = vec![row("", None, None, None)];
    for uci in &root_moves {
        let (outcome, bound) = if uci == "g1f3" {
            (Some(Outcome::Loss), Some(10))
        } else if uci == open_child {
            (None, None)
        } else {
            (Some(Outcome::Win), Some(2))
        };
        rows.push(row(
            uci,
            outcome,
            bound,
            outcome.map(|_| DepthStatus::Bound),
        ));
    }
    let child_moves = legal(open_child);
    assert_eq!(child_moves.len(), 20);
    for uci in &child_moves {
        rows.push(row(
            &format!("{open_child} {uci}"),
            Some(Outcome::Win),
            Some(2),
            Some(DepthStatus::Bound),
        ));
    }
    let an = analyse(&rows);
    // The single-pass classification (derive-once) claims the stale bound.
    let first = an
        .classify("", &HashMap::new())
        .expect("replay")
        .expect("round-1 claim");
    assert_eq!(
        first.value,
        Flip {
            stm_win: true,
            bound: 11
        }
    );
    let claim = an.claim("").expect("converged claim");
    assert_eq!(
        claim.value,
        Flip {
            stm_win: true,
            bound: 4
        }
    );
    assert_eq!(claim.coverage, Coverage::AndComplete);
    assert_eq!(claim.bound_mode, BoundMode::Upper);
    assert_eq!(claim.loss_witnesses, 2);
    assert_eq!(claim.unresolved_replies, 0);
    // The open child is itself an and-complete loss claim (all replies win).
    let child = an.claim(open_child).expect("child claim");
    assert_eq!(
        child.value,
        Flip {
            stm_win: false,
            bound: 3
        }
    );
    assert_eq!(an.verify_all().expect("verifies"), 2);
}

/// The strict polarity: a loss claim requires and-complete coverage, and
/// `exact` needs exact contributors (never an and-complete shortcut).
#[test]
fn loss_flip_requires_and_complete_coverage() {
    let root_moves = legal("");
    assert_eq!(root_moves.len(), 20);
    let declare = || {
        let mut rows = vec![row("", None, None, None)];
        for uci in root_moves.iter().filter(|u| u.as_str() != "a2a3") {
            rows.push(row(
                uci,
                Some(Outcome::Win),
                Some(3),
                Some(DepthStatus::Exact),
            ));
        }
        rows
    };
    let incomplete = declare();
    let an = analyse(&incomplete);
    assert!(an.claim("").is_none(), "incomplete coverage must not claim");
    assert_eq!(an.order().len(), 0);
    let fabricated = Claim {
        value: Flip {
            stm_win: false,
            bound: 4,
        },
        coverage: Coverage::AndComplete,
        bound_mode: BoundMode::Exact,
        loss_witnesses: 0,
        unresolved_replies: 0,
    };
    let err = an.verify("", &fabricated, 0).expect_err("no coverage");
    assert!(err.contains("a2a3"), "must name the reply: {err}");
    assert!(err.contains("has no DB row"), "{err}");
    assert!(err.contains("requires and-complete coverage"), "{err}");

    // Row present but claim-less: the other named defect.
    let mut claimless = declare();
    claimless.push(row("a2a3", None, None, None));
    let an = analyse(&claimless);
    let err = an.verify("", &fabricated, 0).expect_err("unresolved");
    assert!(err.contains("a2a3"), "must name the reply: {err}");
    assert!(err.contains("unresolved"), "{err}");

    // A win claim over a row with no loss witness is refused (defensive: the
    // fixpoint never emits one).
    let no_witness = Claim {
        value: Flip {
            stm_win: true,
            bound: 4,
        },
        coverage: Coverage::OrWitness,
        bound_mode: BoundMode::Upper,
        loss_witnesses: 1,
        unresolved_replies: 0,
    };
    let err = an.verify("", &no_witness, 0).expect_err("no witness");
    assert!(err.contains("no loss witness"), "{err}");

    // Positive variant: full coverage claims; exactness needs exact children.
    let mut full: Vec<DbRow> = vec![row("", None, None, None)];
    for uci in &root_moves {
        full.push(row(
            uci,
            Some(Outcome::Win),
            Some(3),
            Some(DepthStatus::Exact),
        ));
    }
    let an = analyse(&full);
    let claim = an.claim("").expect("and-complete claim");
    assert_eq!(
        claim.value,
        Flip {
            stm_win: false,
            bound: 4
        }
    );
    assert_eq!(claim.coverage, Coverage::AndComplete);
    assert_eq!(claim.bound_mode, BoundMode::Exact);
    assert_eq!(an.verify_all().expect("verifies"), 1);

    full[7].depth_status = Some(DepthStatus::Bound);
    let an = analyse(&full);
    let claim = an.claim("").expect("and-complete claim");
    assert_eq!(claim.bound_mode, BoundMode::Upper);
    assert_eq!(claim.value.bound, 4);
    assert_eq!(an.verify_all().expect("verifies"), 1);
}
